M32 = 0xffffffff


def _cos16(a):
    """FUN_6807cb88 (cos) with a already s16: table lookup, returns the uint32 the C code returns"""
    v = (a >> 4) + ((a >> 3) & 1)
    av = abs(v)
    if av < 0x400:
        return TAB[av] & M32
    return (-TAB[0x800 - av]) & M32


def _mul_div(p, q, d):
    """FUN_6807d2f6: signed 64-bit product, C division by d (truncating toward zero), as a signed int"""
    num = p * q
    qt = abs(num) // abs(d)
    return qt if (num < 0) == (d < 0) else -qt


